<section class="restaurant-location"><div><p class="eyebrow">VISIT OUR RESTAURANT</p><h2>{{ $restaurant->name }}</h2><p>{{ $restaurant->description }}</p><p>{{ $restaurant->address }}</p><a href="tel:{{ preg_replace('/[^+0-9]/','',$restaurant->phone) }}">{{ $restaurant->phone }}</a><p><a href="https://www.google.com/maps/dir/?api=1&amp;destination={{ $restaurant->latitude }},{{ $restaurant->longitude }}" target="_blank" rel="noopener noreferrer">Get directions ↗</a></p></div><div class="location-map" data-location-map data-latitude="{{ $restaurant->latitude }}" data-longitude="{{ $restaurant->longitude }}" data-name="{{ $restaurant->name }}" data-address="{{ $restaurant->address }}" aria-label="Map showing {{ $restaurant->name }}"></div></section>
